use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Read the clock first so `seconds` reflects the start of the run.
        let now = wall_clock::now();

        // One permitted fetch. A transport failure is a value, not a trap,
        // so it yields fetched = 0 rather than failing the node.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let accepted = notifier::notify("heartbeat");

        // The contract requires `notified == true` on every output. If the
        // notifier refuses, there is no valid report to return, so trap
        // rather than emit `notified: false`.
        if !accepted {
            panic!("notifier refused the heartbeat notification");
        }

        HeartbeatReport {
            seconds: now.seconds,
            fetched,
            notified: true,
        }
    }
}

export!(Node);
```

